  "about.founderHeading": "📖 Tentang Pengasas",
  "about.founder.p1": "Hai, saya Concepcion, pengasas Luminous StockHaven.",
  "about.founder.p2": "Saya bukan berasal dari syarikat teknologi besar, dan saya tidak duduk di pejabat korporat. Saya seorang pemilik runcit kecil, sama seperti anda. Saya menguruskan lima kedai e-dagang yang mengkhusus dalam buku dan aksesori buatan tangan untuk pencinta buku.\nSeperti kebanyakan peruncit bebas, saya sampai ke titik putus asa apabila cuba mengurus inventori di banyak lokasi, menjejaki ISBN penerbit di samping SKU buatan tangan saya sendiri, dan mengendalikan pesanan pembekal dengan hamparan yang rumit. Apabila saya mencari aplikasi untuk membantu saya, saya mencuba enam pilihan berbeza. Setiap satu sama ada tidak lengkap sepenuhnya, sangat mengelirukan, atau bersifat pemangsa — mengenakan caj ratusan dolar sebulan untuk alat asas.",
  "about.founder.p3": "Kecewa dengan industri yang memerah pencipta bebas, saya memutuskan untuk membina penyelesaian saya sendiri. Saya membina Luminous StockHaven kerana keperluan, untuk menjalankan perniagaan saya sendiri dengan bersih, cekap, dan dengan ketenangan fikiran sepenuhnya.",
  "about.founder.p4": "Saya memutuskan untuk membuka platform ini kepada orang ramai pada harga yang jujur dan berpatutan, kerana setiap pemilik perniagaan kecil berhak mendapat alat yang benar-benar berfungsi tanpa mempertaruhkan pendapatan mereka. Kami dimiliki secara bebas, sangat melindungi komuniti kami, dan dibina oleh seorang peruncit, untuk para peruncit.",
