  "plans.backToWelcome": "Kembali ke alu-aluan",
  "plans.eyebrow": "Pelan & ciri",
  "plans.title": "Bandingkan pelan StockHaven",
  "plans.intro": "Satu akaun, walau pelan mana yang anda pilih — Business merangkumi sehingga lima perniagaan. Harga adalah bulanan dalam dolar AS, dan pelanggan laman web baharu yang layak boleh menerima satu percubaan tujuh hari merentas Essentials dan Business. Menaik taraf langganan Essentials sedia ada ke Business tidak memulakan semula percubaan atau mewujudkan percubaan percuma lain. Harga pelan laman web adalah sebelum cukai yang berkenaan, jika ada. Caj tepat anda akan ditunjukkan sebelum anda memberi kuasa kepada langganan.",
  "plans.availableAtLaunch": "Tersedia semasa pelancaran mudah alih",
