  "plans.included": "Disertakan",
  "plans.notIncluded": "Tidak disertakan",
  "plans.mobileIncludedNote": "Kedua-dua pelan laman web termasuk teman mudah alih, jadi pelanggan laman web tidak pernah membayar yuran bulanan mudah alih juga.",
  "plans.priceNote": "Essentials ialah $14.99/bulan ditambah cukai yang berkenaan, jika ada. Business ialah $29.99/bulan ditambah cukai yang berkenaan, jika ada. Sebarang cukai yang diperlukan ditentukan semasa pembayaran pembekal dan mesti muncul dalam jumlah akhir sebelum bayaran. Halaman perbandingan ini bukan sebut harga cukai atau kebenaran pembayaran.",
  "plans.mobilePriceNote": "Pelan mudah alih sahaja ialah $4.99/bulan pada harga asas AS yang dimaksudkan. App Store atau Google Play menunjukkan harga langganan tempatan sebenar dan sebarang cukai yang berkenaan sebelum pembelian. Elaun produk, tapak dan kakitangannya ditetapkan semasa pelancaran, berasingan daripada peringkat laman web.",
  "plans.planChangeNote": "Perubahan pelan laman web mesti disahkan oleh pembekal pengebilan. Harga baharu, tarikh berkuat kuasa dan sebarang prorata akan dijelaskan sebelum perubahan diberi kuasa. Penaiktarafan tidak sepatutnya mewujudkan langganan kedua.",
  "plans.providerNote": "Harga, caj dan percubaan dikendalikan oleh pembekal yang anda langgan melaluinya — App Store, Google Play, laman web atau Shopify — bukan oleh halaman ini.",
