  "upgrade.intro": "Pelanggan baharu yang layak boleh menerima satu percubaan {days} hari bagi setiap akaun, bukan satu percubaan bagi setiap pelan. Bertukar dari Essentials ke Business tidak pernah memulakan percubaan percuma lain. Anda berada di",
