  "upgrade.providerConfirmNote": "Perubahan pelan memerlukan pengesahan daripada pembekal pengebilan. Sebarang perbezaan harga, prorata dan tarikh berkuat kuasa mesti ditunjukkan sebelum anda meluluskan perubahan. Penaiktarafan tidak boleh mewujudkan langganan serentak kedua.",
  "upgrade.chargedThroughProviderNote": "Perubahan pelan dicaj melalui pembekal pengebilan. Anda boleh membatalkan langganan anda dari halaman ini menggunakan butang Batalkan Langganan di bawah pelan semasa anda, atau dari Tetapan. Membatalkan menghentikan pembaharuan akan datang pada akhir tempoh berbayar anda; ia tidak pernah menamatkan akses anda serta-merta. Ruang kerja percuma sedia ada tidak dicaj dengan melihat pilihan ini.",
