  "settings.details.address": "Alamat",
  'settings.details.taxRate': 'Kadar cukai saya',
  'settings.details.taxRateHint': 'Tetapkan sekali. Setiap pesanan jualan baharu mengisi cukainya sendiri daripada kadar ini — anda masih boleh menukar cukai pada mana-mana satu pesanan.',
  "settings.details.taxMode": "Cara pesanan mendapat cukainya",
  "settings.details.taxModeFixed": "Kadar tetap saya",
  "settings.details.taxModeAutomatic": "Automatik — mengikut negeri pelanggan",
  "settings.details.taxModeHint": "Mod tetap menggunakan kadar anda pada setiap pesanan baharu. Mod automatik mengisi cukai pesanan baharu dengan kadar asas negeri pelanggan sebaik sahaja negeri berada pada pesanan, dan mengisinya semula jika negeri berubah. Ini ialah kadar asas negeri — cukai tempatan mungkin menambah lagi. Pesanan tanpa negeri, atau dari luar AS, menggunakan kadar tetap anda di atas.",
  'settings.details.gs1Prefix': "Awalan syarikat GS1",
  'settings.details.gs1PrefixHint': "Hanya jika anda mempunyai lesen awalan daripada GS1. Tetapkan sekali dan penjana kod dalam borang produk boleh membuat kod UPC dan EAN runcit sebenar daripada nombor anda sendiri — setiap satu digunakan sekali sahaja dan tidak pernah digunakan semula. Biarkan kosong jika anda tiada; aplikasi tidak pernah mereka awalan.",
  'settings.details.gs1LearnMore': "Baru dengan GS1? Jika anda tinggal di negara anda sendiri, gunakan pautannya untuk mengetahui lebih lanjut; jika anda tinggal di Amerika Syarikat, gunakan pautan GS1 US.",
