  "settings.logout": "Log keluar",
  "settings.pastDue.body": "Pembayaran terakhir anda tidak berjaya. Anda kekal mendapat penggunaan penuh selama 14 hari dari pembayaran yang gagal semasa anda membaikinya. Jika tidak dibaiki, langganan akan dibatalkan, ruang kerja menjadi lihat-sahaja selama 15 hari, dan kemudian akaun dan semua maklumatnya dipadamkan. Membayar pada bila-bila masa sebelum pemadaman mengembalikan semuanya. Jika anda tidak pasti apa yang perlu dilakukan, hubungi sokongan di theluminousbookshop@outlook.com.",
