  "workforce.messages.help": "Mesej peribadi satu lawan satu dengan pasukan anda — tiada aplikasi lain diperlukan. Hanya dua orang dalam perbualan yang boleh membacanya, serta pemilik perniagaan, yang menyelia kedai mereka.",
