  "recovery.emailMeCodeHint": "Jika anda menyediakan e-mel sandaran, kami akan menghantar kod 6 digit ke sana. Untuk melindungi akaun anda, halaman ini sentiasa menjawab dengan cara yang sama — sama ada kod dihantar atau tidak.",
  "recovery.codeSent": "Jika e-mel sandaran anda ada dalam fail, kod 6 digit sedang dalam perjalanan ke sana sekarang. Ia luput dalam 10 minit.",
