  "recovery.changeIntro": "Anda masuk — untuk satu langkah sahaja: pilih e-mel baharu untuk akaun anda. Kedai, inventori dan akses pasukan anda semuanya berpindah bersamanya.",
  "recovery.doneBody": "E-mel akaun anda telah ditukar dan log masuk ini kini ialah log masuk biasa anda semula. Selamat kembali.",
