  "settings.security.title": "Keselamatan & kunci ganti",
  "settings.security.description": "Sediakan kunci ganti anda SEBELUM anda memerlukannya: jika anda kehilangan akses kepada e-mel akaun anda, itulah cara anda mendapatkan kembali kedai anda.",
  "settings.security.genericError": "Sesuatu tidak kena. Sila cuba lagi.",
  "settings.security.accountEmail": "E-mel akaun",
  "settings.security.backupCodesTitle": "Kod sandaran",
  "settings.security.backupCodesDesc": "Kunci ganti sekali guna. Cetaknya atau tulis dan simpan di tempat selamat — setiap satu boleh membawa anda kembali sekali jika anda kehilangan e-mel anda.",
  "settings.security.codesRemaining": "Kod sandaran yang belum digunakan tinggal: {count}",
