  "settings.security.codesOnceWarning": "Kod ini hanya ditunjukkan sekali — kami hanya menyimpan salinan yang dikacau, jadi kami pun tidak boleh menunjukkannya lagi. Menjana set baharu membatalkan setiap kod lama.",
  "settings.security.printCodes": "Cetak kod ini",
  "settings.security.backupEmailTitle": "E-mel sandaran",
  "settings.security.backupEmailDesc": "Alamat e-mel kedua yang anda kawal. Jika e-mel utama anda tidak dapat dicapai, kod pemulihan boleh dihantar ke sini sebaliknya.",
  "settings.security.backupEmailLabel": "Alamat e-mel sandaran",
