  "print.carrier.title": "Label pembawa anda",
  "print.carrier.desc": "Beli kos pos daripada pembawa, seperti yang anda lakukan hari ini — aplikasi ini tidak pernah menjual kos pos, jadi harga yang anda bayar sentiasa harga pembawa itu sendiri. Simpan fail label di sini dan label itu kekal pada pesanan ini selama-lamanya: rekod anda, sedia di tangan sekiranya berlaku sesuatu.",
