  "print.style.desc": "Jadikan dokumen anda milik anda. Pilihan ini menghias invois, resit, slip pembungkusan, dokumen pemulangan, helaian produk, helaian kiraan, dan senarai ambil anda — dan diingati untuk perniagaan anda.",
