  "training.lessons.owner-shipping-labels.step1": "Pusat Cetakan mempunyai gaya Label penghantaran dalam kedua-dua pelan: pilih pesanan pelanggan dan cetak label 4×6 dengan nama dan alamat pembeli serta perniagaan anda sebagai pengirim.",
  "training.lessons.owner-shipping-labels.step2": "Label ini berlabel putih, seperti setiap dokumen pelanggan: ia hanya memuat nama perniagaan anda — tidak sesekali nama aplikasi ini — supaya bungkusan dari kedai anda kelihatan seperti berasal dari kedai anda.",
  "training.lessons.owner-shipping-labels.step3": "Alamat pelanggan disimpan bersama pesanan mereka selama 90 hari selepas pesanan terakhir mereka, dan label bermula dari alamat tersimpan pesanan apabila ada; alamat yang ditaip semasa cetakan untuk label sekali sahaja tidak disimpan semula. Nama masih diisi dari pesanan supaya label sepadan dengan kertas kerja.",
  "training.lessons.owner-shipping-labels.step4": "Label ini dicetak melalui empat sambungan yang sama seperti semua label — Bluetooth, Wi-Fi, Ethernet dan USB — dan pencetak terma 4×6 ialah saiz piawainya.",
  "training.lessons.owner-shipping-labels.step5": "Membeli kos pos daripada pembawa sebagai gantinya? Di bahagian yang sama ini anda boleh memuat naik fail label pembawa — PDF, PNG, atau JPG — dan label itu kekal tersimpan pada pesanan selama-lamanya: rekod anda, sedia di tangan sekiranya berlaku sesuatu. Ia dicetak dalam saiz sebenarnya 4×6. Aplikasi tidak pernah menjual kos pos, jadi harga pembawa ialah satu-satunya harga — dan sentiasa harga yang betul.",
  "training.lessons.owner-shipping-labels.title": "Label penghantaran untuk pesanan pelanggan",
  "training.lessons.print-shipping-label.step1": "Apabila pesanan sedia untuk dihantar, buka Pusat Cetakan, pilih gaya Label penghantaran, kemudian pilih pesanan pelanggan. Nama pembeli diisi daripada pesanan.",
  "training.lessons.print-shipping-label.step2": "Semak alamat yang dituju bungkusan. Apabila pesanan membawa alamat pelanggan — disimpan selama 90 hari selepas pesanan terakhir mereka — ia diisi untuk anda; alamat yang anda taip semasa cetakan tidak disimpan semula, jadi semak poskod dan baris terakhir dengan teliti sebelum anda mencetak.",
  "training.lessons.print-shipping-label.step3": "Nama perniagaan anda dicetak di atas sebagai pengirim. Jika anda mahu alamat anda juga pada label, taipkannya dalam kotak alamat pengirim; biarkan kosong jika anda lebih suka ia tidak ditunjukkan.",
  "training.lessons.print-shipping-label.step4": "Cetak pada label 4×6 — pencetak label terma ialah pilihan biasa — atau pada mana-mana pencetak melalui butang cetak penyemak imbas. Lekatkan label rata pada bungkusan, di tempat ia tidak akan terlipat di tepi.",
  "training.lessons.print-shipping-label.step5": "Jika kos pos dibeli daripada pembawa, simpan fail label mereka pada pesanan sebagai gantinya: muat naik PDF, PNG, atau JPG yang diberikan pembawa kepada anda dalam bahagian Label pembawa anda. Ia kekal pada pesanan sebagai rekod anda dan dicetak dalam saiz sebenarnya 4×6 — dan label alamat aplikasi sendiri sentiasa ada di situ apabila anda lebih suka menggunakannya.",
  "training.lessons.print-shipping-label.title": "Cetak label penghantaran",
  "pos.provider.clover": "Clover",
  "pos.provider.toast": "Toast",
