  "settings.personal.subtitle": "Akaun, keselamatan dan pilihan anda sendiri. Tetapan perniagaan kekal pada pemilik.",
  "staffLib.area.settingsAccess": "Akses tetapan",
  "staffLib.perm.settingsTaxRate": "Kadar cukai",
