  "staffLib.perm.alertsView": "Lihat amaran stok rendah",
  "staffLib.perm.productsReorder": "Tukar titik pesanan semula",
  "staffLib.area.lowStockAccess": "Stok rendah",
  "staff.memberDialog.lowStockAccessHint": "Dengan tanda pertama, orang ini melihat amaran stok rendah — kotak Perlu perhatian, halaman Stok rendah dan tanda paras rendah. Dengan tanda kedua, mereka boleh menukar titik pesanan semula produk; tanpanya, kotak Titik pesanan semula tetap kelihatan, tetapi perubahan padanya tidak akan disimpan.",
  "apiErrors.reorderChangeReserved": "Hanya pemilik, atau ahli pasukan yang dibenarkan oleh pemilik untuk menukar titik pesanan semula, boleh menukar titik pesanan semula.",
  "apiErrors.alertsViewReserved": "Hanya pemilik, atau ahli pasukan yang dibenarkan oleh pemilik untuk melihat amaran stok rendah, boleh melihat amaran stok rendah.",
