  "settings.policyQuiz.empty": "Tiada soalan lagi. Tanpa soalan, latihan ini hanyalah bacaan.",
  "settings.policyQuiz.expected": "Jawapan yang dijangkakan",
  "settings.policyQuiz.expectedHint": "Jawapan yang anda jangkakan, dengan kata-kata anda. Jawapan yang hampir sepadan perkataan demi perkataan dikira betul di tempat itu juga; yang lain datang kepada anda untuk dilihat.",
  "settings.policyQuiz.hint": "Tulis soalan tentang dokumen ini untuk pasukan anda. Seseorang menjawabnya dalam Latihan apabila anda menanda latihan ini untuk mereka dalam rekod Kakitangan mereka. Tiada had kepada berapa banyak soalan yang anda tulis.",
  "settings.policyQuiz.mcLabel": "Aneka pilihan",
  "settings.policyQuiz.openLabel": "Soalan terbuka",
  "settings.policyQuiz.passLine": "Garisan lulus",
  "settings.policyQuiz.passLineHint": "Skor — mengira jawapan aneka pilihan sahaja — yang diperlukan seseorang untuk menyelesaikan latihan ini.",
  "settings.policyQuiz.question": "Soalan",
  "settings.policyQuiz.remove": "Buang",
  "settings.policyQuiz.save": "Simpan soalan",
  "settings.policyQuiz.saved": "Soalan disimpan.",
  "settings.policyQuiz.title": "Soalan untuk pasukan anda",
  "staff.memberDialog.trainingAccessHint": "Membaca polisi kedai dan terma adalah untuk semua orang. Tanda ini memberikan latihan kuiz yang dibina pemilik di sebelah setiap dokumen dalam Tetapan.",
  "staffLib.area.trainingAccess": "Latihan kuiz polisi",
  "staffLib.perm.trainingPoliciesQuiz": "Latihan kuiz Polisi Kedai",
  "staffLib.perm.trainingTermsQuiz": "Latihan kuiz Terma & Syarat",
  "training.comment.placeholder": "Apa-apa tentang pelajaran ini…",
  "training.comment.send": "Hantar komen",
  "training.comment.sent": "Komen anda telah difailkan kepada pemilik.",
  "training.comment.title": "Tinggalkan komen untuk pemilik",
  "training.lessons.download-app.step1": "Luminous StockHaven boleh tinggal di telefon atau komputer anda seperti aplikasi sebenar — tiada kedai aplikasi diperlukan.",
  "training.lessons.download-app.step2": "Buka Tetapan dan cari kad Muat turun aplikasi. Ia ada di sana untuk setiap peranan, pada kedua-dua pelan.",
  "training.lessons.download-app.step3": "Ketik butang pasang dan ikut arahan peranti anda. Aplikasi mendarat di skrin utama anda dengan nama dan ikon kedai.",
  "training.lessons.download-app.step4": "Bukanya dari skrin utama anda mulai sekarang — ia melog masuk anda dengan cara yang sama dan menunjukkan kedai yang sama.",
  "training.lessons.download-app.title": "Muat turun aplikasi ke peranti anda",
  "training.lessons.mgr-tax-rate.step1": "Pesanan boleh membawa kadar cukai jualan. Pemilik menetapkan kadar itu sendiri dalam Tetapan; ia adalah satu kadar untuk seluruh kedai.",
  "training.lessons.mgr-tax-rate.step2": "Apabila pemilik menanda bahagian cukai untuk anda dalam rekod Kakitangan anda, kadar itu muncul dalam Tetapan anda juga, dan anda boleh mengekalkannya terkini di sana.",
  "training.lessons.mgr-tax-rate.step3": "Kadar itu adalah peratus — 8.25 bermakna pelanggan membayar cukai 8.25% di atas barangan pesanan.",
  "training.lessons.mgr-tax-rate.step4": "Apabila kadar berubah, pesanan baru menggunakan kadar baru. Pesanan yang sudah dibuat mengekalkan kadar semasa ia dibuat.",
  "training.lessons.mgr-tax-rate.step5": "Jika pemilik menukar cukai kepada Automatik, pesanan baharu mengisi cukainya dengan kadar asas negeri pelanggan sebaik sahaja negeri berada pada pesanan, dan mengisinya semula jika negeri berubah. Ini ialah kadar asas negeri; cukai tempatan mungkin menambah lagi. Pesanan tanpa negeri, atau dari luar AS, menggunakan kadar tetap kedai — dan cukai yang ditaip pada pesanan sentiasa diguna pakai.",
  "training.lessons.mgr-tax-rate.title": "Kadar cukai kedai",
  "training.lessons.owner-confidentiality.step5": "Inilah keseluruhan peta. Pasukan anda melihat kerja mereka sendiri — jadual mereka, tugas mereka, slip gaji mereka, mesej mereka, dan skrin kedai yang dibuka oleh peranan mereka. Mereka tidak pernah melihat percubaan anda, pelan apa yang digunakan perniagaan, berapa kos pelan itu, sama ada pembayaran berjaya, atau bahawa had pelan telah dicapai. Permukaan wang — pengebilan, invois, kaedah pembayaran — hanya untuk pemilik, sentiasa.",
  "training.lessons.owner-confidentiality.step6": "Jika akaun pernah dihentikan, inilah mesej tepat yang dilihat pasukan anda: “Perubahan dimatikan sekarang. Pada masa ini tiada apa yang boleh ditambah atau diubah — tanya pemilik perniagaan jika anda memerlukan sesuatu.” Tiada apa di dalamnya yang menyebut pelan, harga, atau pembayaran.",
  "training.lessons.owner-confidentiality.step7": "Dan apabila had pelan yang menghentikan sesuatu, inilah mesej tepatnya: “Ini tidak boleh ditambah sekarang — mintalah kepada pemilik perniagaan.” Ia tidak pernah mengatakan had telah dicapai — itu kekal antara anda dan aplikasi.",
  "training.lessons.staff-builds.step1": "Satu binaan menggabungkan produk menjadi satu benda yang boleh dijual — satu berkas, satu kit, satu set hadiah. Binaan tinggal dalam skrin Binaan dalam menu.",
  "training.lessons.staff-builds.step2": "Buka satu binaan untuk melihat apa yang masuk ke dalamnya: setiap produk bahagian dan berapa banyak daripada setiap satu yang digunakan binaan itu.",
  "training.lessons.staff-builds.step3": "Apabila binaan dibuat atau dijual, stok bahagian-bahagiannya bergerak bersamanya — aplikasi mengekalkan kiraan yang jujur untuk anda.",
  "training.lessons.staff-builds.step4": "Jika satu bahagian hilang atau kiraan kelihatan salah, beritahu pengurus anda daripada meneka — binaan menyentuh banyak produk sekaligus.",
  "training.lessons.staff-builds.title": "Binaan dan berkas",
  "training.lessons.staff-cross-store.step1": "Apabila perniagaan anda mempunyai lebih daripada satu kedai atau tapak, kedai-kedai boleh meminta stok antara satu sama lain. Permintaan itu mendarat dalam peti masuk antara kedai.",
  "training.lessons.staff-cross-store.step2": "Buka peti masuk dari menu untuk melihat apa yang diminta kedai lain, dan apa yang telah dihantar ke kedai anda.",
  "training.lessons.staff-cross-store.step3": "Jawab permintaan hanya dengan cara yang ditunjukkan pengurus anda — menghantar stok keluar mengubah kiraan kedai anda sendiri.",
  "training.lessons.staff-cross-store.step4": "Jika permintaan kelihatan salah — item yang salah, atau lebih daripada yang anda ada — jangan teka. Tandakannya kepada pengurus anda.",
  "training.lessons.staff-cross-store.title": "Peti masuk antara kedai",
  "training.lessons.staff-reports.step1": "Laporan mengumpulkan nombor kedai — jualan, stok dan banyak lagi — ke satu tempat. Laporan tinggal dalam menu.",
  "training.lessons.staff-reports.step2": "Buka satu laporan untuk melihat nombornya bagi tarikh yang diliputinya. Tarikh adalah sebahagian daripada laporan: laporan yang sama pada minggu yang berbeza menceritakan kisah yang berbeza.",
  "training.lessons.staff-reports.step3": "Sesetengah laporan boleh disimpan keluar dari aplikasi sebagai fail. Simpan laporan keluar hanya apabila pengurus atau pemilik memintanya.",
  "training.lessons.staff-reports.step4": "Nombor laporan datang dari kerja sebenar kedai — pesanan, kiraan dan pergerakan — jadi catatan yang jujur di tempat lain mengekalkan laporan yang benar.",
  "training.lessons.staff-reports.title": "Membaca laporan",
  "training.lessons.welcome-basics.step6": "Apabila anda selesai, log keluar: pautan Log keluar berada di bahagian paling bawah setiap halaman, tepat di atas baris hak cipta. Log keluar melog keluar anda di mana-mana, pada setiap peranti — jadi tiada siapa boleh masuk ke akaun anda pada skrin yang dikongsi.",
