  "plansLib.includes.profilePhotos": "Foto profil untuk seluruh pasukan anda, diluluskan oleh pemilik",
  "apiErrors.notFound.photoFound": "Foto tidak ditemui.",
  "apiErrors.profileOwnerNameOnly": "Hanya pemilik perniagaan boleh menetapkan nama pemilik.",
  "apiErrors.profilePhotosApproveOwnerOnly": "Hanya pemilik perniagaan boleh meluluskan foto pasukan.",
  "apiErrors.profilePhotosNoneWaiting": "Ahli pasukan itu tiada foto yang menunggu kelulusan.",
  "apiErrors.profileOwnerNameTooLong": "Pastikan nama anda 80 aksara atau kurang.",
  "training.lessons.your-profile-photo.title": "Foto profil anda",
  "training.lessons.your-profile-photo.step1": "Foto anda muncul di sebelah nama anda di bahagian atas apl, pada halaman Kakitangan, dan di sebelah mesej anda — sebaik sahaja pemilik meluluskannya. Sehingga itu, hanya parap anda yang ditunjukkan.",
  "training.lessons.your-profile-photo.step2": "Buka Tetapan dan cari Foto profil anda. Pilih foto diri anda dan hantarkannya. Ia dihantar kepada pemilik untuk kelulusan — ia tidak muncul di mana-mana semasa menunggu.",
  "training.lessons.your-profile-photo.step3": "Apabila pemilik meluluskannya, loceng anda berbunyi dan foto anda mula ditunjukkan. Jika ia tidak diluluskan, pilih foto yang berbeza dan hantar foto itu sebaliknya.",
  "training.lessons.your-profile-photo.step4": "Menukar foto anda berfungsi dengan cara yang sama: foto baharu menunggu kelulusan, dan foto semasa anda kekal di tempatnya sehingga foto baharu diluluskan. Jika perubahan tidak diluluskan, anda mengekalkan foto anda yang satu lagi.",
  "training.lessons.owner-profile-photos.title": "Foto profil dan nama anda",
  "training.lessons.owner-profile-photos.step1": "Foto setiap orang ditunjukkan di sebelah namanya di bahagian atas apl, pada halaman Kakitangan anda, dan di sebelah mesej mereka. Foto ahli pasukan tidak muncul di mana-mana sehingga anda meluluskannya — kelulusan adalah milik anda sahaja, dan tiada siapa boleh meluluskan foto mereka sendiri.",
  "training.lessons.owner-profile-photos.step2": "Apabila seseorang menghantar foto, loceng anda berbunyi. Buka halaman Kakitangan untuk melihatnya, kemudian pilih Luluskan atau Tidak luluskan. Jika anda tidak meluluskannya, orang itu diberitahu untuk memilih foto lain.",
  "training.lessons.owner-profile-photos.step3": "Jika seseorang menukar fotonya, foto baharu menunggu kelulusan anda dengan cara yang sama. Foto semasanya kekal di tempatnya semasa menunggu — dan kekal jika anda tidak meluluskan perubahan itu.",
  "training.lessons.owner-profile-photos.step4": "Foto anda sendiri tidak memerlukan kelulusan: tetapkannya dalam Tetapan, di bawah Foto profil anda. Kad yang sama memegang nama anda — nama yang anda tetapkan di sana menggantikan perkataan Pemilik di mana-mana pasukan anda melihatnya, dalam apl dan dalam Mesej.",
  "payroll.dd.corrected": "Borang yang dibetulkan",
  "payroll.dd.correctedDone": "Butiran anda yang dibetulkan telah dihantar kepada pemilik.",
  "payroll.dd.correctionNotice": "Pemilik telah menghantar semula borang anda supaya anda boleh membetulkannya. Semak setiap digit, tandatangani, dan hantar semula.",
  "payroll.dd.correctionWaiting": "Dihantar semula — menunggu borang mereka yang dibetulkan",
  "payroll.dd.fixHelp": "Jika digit salah, betulkan butiran anda dan hantar semula borang. Borang baharu anda yang ditandatangani menggantikan yang lama, dan pemilik diberitahu bahawa ia telah dibetulkan.",
  "payroll.dd.fixMistake": "Betulkan kesilapan",
