  "staff.memberDialog.clockAccessHint": "Khusus manajer — dengan centang ini, manajer ini dapat membuka jendela panggilan masuk (membiarkan seseorang bekerja saat mereka tidak terjadwal) dan mengoreksi catatan waktu dari halaman Staf. Centang ini tidak berpengaruh untuk staf.",
