  "staff.documents.openFile": "Buka",
  "staff.documents.remove": "Alih keluar",
  "staff.documents.removeTitle": "Alih keluar dokumen ini?",
  "staff.documents.removeBody": "Ini mengalih keluar “{title}” daripada fail {name}. Versi lain kekal.",
  "staff.documents.removedToast": "Dokumen dialih keluar",
