  "nav.xstoreMessages": "Mesej antara kedai",
  "plansLib.businessIncludes.xstoreMessages": "Mesej antara kedai — seluruh pasukan anda, merentas setiap perniagaan",
  "xstore.title": "Mesej antara kedai",
  "xstore.help": "Semua orang dalam akaun ini, dari semua perniagaan anda, dalam satu peti masuk. Mesej sesiapa sahaja di sini — teks atau suara, dengan tanda dihantar dan dibaca. Mesej dalam kedai anda kekal seperti sedia ada.",
  "xstore.empty": "Belum ada perbualan lagi. Mulakan satu dengan Mesej baharu.",
  "xstore.noPeople": "Belum ada orang lain untuk dimesaj. Orang akan muncul di sini sebaik sahaja mereka menyertai salah satu perniagaan anda dan log masuk.",
  "xstore.deliveredLabel": "Dihantar",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "Mesej antara kedai adalah sebahagian daripada pelan Business.",
  "apiErrors.invalidValue.personNotPartAccount": "Orang itu bukan sebahagian daripada akaun ini.",
  "training.lessons.owner-xstore-messages.title": "Mesej merentas kedai anda, untuk pemilik",
  "training.lessons.owner-xstore-messages.step1": "Mesej antara kedai ialah peti masuk kedua, berasingan daripada Mesej. Mesej adalah untuk kedai tempat anda berada; pintu ini mencapai semua orang dalam akaun anda, dalam setiap perniagaan yang anda miliki — sehingga lima perniagaan.",
  "training.lessons.owner-xstore-messages.step2": "Buka Mesej antara kedai daripada menu dan mulakan perbualan dengan sesiapa sahaja dalam senarai. Senarai ini menunjukkan setiap ahli pasukan dari semua perniagaan anda yang telah log masuk, bersama kedai tempat mereka bekerja.",
  "training.lessons.owner-xstore-messages.step3": "Foto turut dipaparkan: setiap orang menunjukkan foto profil mereka yang diluluskan, atau huruf awal nama mereka jika tiada. Setiap mesej membawa tarikh dan masa ia dihantar.",
  "training.lessons.owner-xstore-messages.step4": "Di bawah mesej anda sendiri, anda boleh melihat Dihantar sebaik sahaja mesej sampai, dan Dibaca sebaik sahaja orang lain membuka perbualan. Nota suara juga berfungsi di sini, sama seperti dalam Mesej.",
  "training.lessons.owner-xstore-messages.step5": "Perbualan di sini adalah peribadi antara dua orang di dalamnya. Pemantauan Mesej dalam kedai anda tidak menjangkau antara kedai.",
  "training.lessons.mgr-xstore-messages.title": "Mesej merentas kedai anda, untuk pengurus",
  "training.lessons.mgr-xstore-messages.step1": "Mesej antara kedai mencapai semua orang dalam akaun ini, merentas setiap perniagaan — bukan hanya kedai tempat anda berada. Ia berada dalam menu, berasingan daripada Mesej.",
  "training.lessons.mgr-xstore-messages.step2": "Mulakan perbualan daripada senarai: setiap ahli pasukan yang telah log masuk ada di sana, dengan kedai tempat mereka bekerja di sebelah nama mereka.",
  "training.lessons.mgr-xstore-messages.step3": "Hantar teks, atau rakam nota suara. Sebelum nota suara dihantar, anda boleh mendengarnya semula, membuangnya, atau menghantarnya — sama seperti dalam Mesej.",
  "training.lessons.mgr-xstore-messages.step4": "Mesej anda menunjukkan Dihantar apabila ia sampai dan Dibaca apabila orang lain membuka perbualan. Foto di sebelah setiap nama ialah foto profil orang itu yang diluluskan.",
  "training.lessons.staff-xstore-messages.title": "Mesej merentas kedai anda",
  "training.lessons.staff-xstore-messages.step1": "Mesej antara kedai ialah tempat anda boleh menghubungi sesiapa sahaja dalam akaun ini, dalam mana-mana perniagaan pemilik — soalan untuk kedai lain tidak perlu menunggu lagi.",
  "training.lessons.staff-xstore-messages.step2": "Bukanya daripada menu, pilih orangnya, dan tulis. Jika orang yang anda perlukan tiada dalam senarai, mereka belum log masuk lagi — mereka akan muncul sebaik sahaja mereka log masuk.",
  "training.lessons.staff-xstore-messages.step3": "Anda juga boleh menghantar nota suara di sini: rakam, dengar semula, kemudian hantar atau buang. Setiap mesej menunjukkan tarikh dan masa ia dihantar.",
  "training.lessons.staff-xstore-messages.step4": "Apabila anda menghantar mesej, ia menunjukkan Dihantar sebaik sahaja ia sampai, dan Dibaca sebaik sahaja orang lain membuka perbualan. Perbualan adalah peribadi antara anda dan orang lain itu.",
