  "print.transferQuantity": "Jumlah",
  "training.lessons.owner-restaurant-ops.title": "Operasional restoran, untuk pemilik",
  "training.lessons.owner-restaurant-ops.step1": "Invois pembekal berada di sudut Restoran. Masukkan apa yang ditagihkan pembekal, terhubung ke pesanan pembeliannya, dan aplikasi menyemaknya tiga arah — dipesan, diterima dan ditagihkan, bersebelahan — dan menandai baris mana pun yang kurang, lebih, atau ditagihkan dengan harga berbeda.",
  "training.lessons.owner-restaurant-ops.step2": "Saat baris invois menagih produk dengan harga berbeda dari kos yang tercatat, amaran harga terbuka di laman invois. Menerima amaran memperbarui kos produk menjadi harga yang ditagihkan; mengetepikannya membiarkan kos apa adanya.",
  "training.lessons.owner-restaurant-ops.step3": "Log sisa mencatat semua yang dibuang dapur, dengan sebab — kerosakan, kelebihan pengeluaran, kesilapan persediaan, pemulangan, tumpahan, atau lainnya — dan mencatatnya mengambil stok dari rak dengan sendirinya. Kelompok luput disenaraikan luput lebih dulu, keluar lebih dulu, sehingga tarikh pakai paling awal dipakai lebih dulu, dan Anda dapat mencetak label tarikh untuk kelompok yang Anda tanda.",
  "training.lessons.owner-restaurant-ops.step4": "Matriks alergen menghitung alergen setiap hidangan dari bahan resipinya, terhadap sembilan alergen utama, sehingga pertanyaan tamu dijawab dari catatan, bukan dari ingatan. Catatan suhu, papan barang habis dan makanan staf terbuka untuk seluruh pasukan — tidak perlu tanda — karena pencatatan harian hanya berhasil bila siapa pun dapat melakukannya.",
  "training.lessons.owner-restaurant-ops.step5": "Kejuruteraan menu menempatkan setiap hidangan menurut seberapa banyak terjual dan seberapa banyak hasilnya: bintang, kuda penarik, teka-teki dan anjing. Laman varians membandingkan apa yang dikatakan resipi seharusnya meninggalkan rak terhadap makanan staf, sisa dan semua hal lain yang keluar — apa yang tersisa adalah tanpa penjelasan. Eksport perakaunan mengumpulkan pembelian yang diterima, sisa, makanan staf dan pengurangan resipi menjadi satu buku besar untuk pembukuan Anda.",
  "training.lessons.staff-restaurant-daily.title": "Kebiasaan harian dapur",
  "training.lessons.staff-restaurant-daily.step1": "Saat sesuatu dibuang, catat di log sisa pada hari yang sama: apa itu, berapa banyak, dan sebabnya — kerosakan, kelebihan pengeluaran, kesilapan persediaan, pemulangan, tumpahan, atau lainnya. Mencatatnya mengambil stok dari rak dengan sendirinya; Anda tidak melaraskan stok secara terpisah.",
  "training.lessons.staff-restaurant-daily.step2": "Catat setiap suhu peti sejuk, penyejuk beku dan penyimpan panas saat Anda menyemaknya. Catatan menyimpan nama dan waktu Anda, dan menandai pembacaan apa pun di luar julat aman — tulis apa yang Anda lakukan tentang hal itu sebagai tindakan perbaikan.",
  "training.lessons.staff-restaurant-daily.step3": "Papan barang habis adalah apa yang habis, saat ini. Pasang item begitu habis, agar seluruh pasukan tahu sekaligus, dan hapus saat kembali — papan menyimpan siapa yang menghapusnya dan bila.",
  "training.lessons.staff-restaurant-daily.step4": "Saat pasukan makan, catat sebagai makanan staf. Setiap makanan mengambil hidangannya dari rak dan memakai bahan resipi hidangan itu, sama seperti penjualan. Makanan staf adalah kos nyata hari itu, dan tempatnya ada di catatan.",
  "training.lessons.mgr-restaurant-invoices.title": "Invois, kelompok dan menjalankan kelompok",
  "training.lessons.mgr-restaurant-invoices.step1": "Pemilik telah mempercayakan tanda Buat resipi kepada Anda, dan tanda itu juga membuka pekerjaan pembangunan dapur: invois pembekal, kelompok luput dan pengeluaran kelompok. Masukkan invois pembekal dengan baris-barisnya — produk, jumlah dan kos yang ditagihkan — dan hubungkan ke pesanan pembeliannya bila ada.",
  "training.lessons.mgr-restaurant-invoices.step2": "Dengan pesanan pembelian terhubung, invois disemak tiga arah, baris demi baris: apa yang dipesan, apa yang diterima dan apa yang ditagihkan. Baris dapat kembali cocok, kurang, lebih, ditagihkan dengan harga berbeda, atau tidak ada pada pesanan sama sekali.",
  "training.lessons.mgr-restaurant-invoices.step3": "Saat harga yang ditagihkan berbeda dari kos produk yang tercatat, amaran harga terbuka. Menerima amaran menetapkan kos produk menjadi harga baru yang ditagihkan; mengetepikannya tidak mengubah apa pun. Hanya satu amaran terbuka yang berlaku untuk invois dan produk yang sama pada satu waktu.",
  "training.lessons.mgr-restaurant-invoices.step4": "Terima stok sebagai kelompok luput dengan tarikh pakainya, dan laman luput menjaga kelompok luput lebih dulu, keluar lebih dulu. Menjalankan kelompok membuat resipi sejumlah kali yang ditetapkan: memakai bahan-bahan resipi dan menaruh produk persediaan yang jadi di rak — resipi harus terhubung ke produk persediaan itu terlebih dahulu.",
  "training.lessons.mgr-restaurant-reports.title": "Kejuruteraan menu, varians dan pembukuan",
  "training.lessons.mgr-restaurant-reports.step1": "Pemilik telah mempercayakan tanda Wang hidangan kepada Anda, dan tanda itu juga membuka laporan wang dapur: kejuruteraan menu, varians dan eksport perakaunan. Angka-angka ini tetap di dalam perniagaan, seperti semua wang hidangan.",
  "training.lessons.mgr-restaurant-reports.step2": "Kejuruteraan menu menempatkan setiap hidangan menurut seberapa banyak terjual dan seberapa banyak hasilnya dalam tempoh. Bintang laris dan menghasilkan banyak; kuda penarik laris tetapi menghasilkan sedikit; teka-teki menghasilkan banyak tetapi laris sedikit; anjing tidak keduanya.",
  "training.lessons.mgr-restaurant-reports.step3": "Laman varians bekerja per produk: apa yang dikatakan resipi seharusnya meninggalkan rak, di samping makanan staf, sisa dan setiap pengeluaran stok lainnya. Apa pun yang tersisa adalah tanpa penjelasan — dan tanpa penjelasan adalah angka yang harus dijelaskan.",
  "training.lessons.mgr-restaurant-reports.step4": "Eksport perakaunan adalah satu buku besar untuk dapur: pembelian yang diterima, sisa, makanan staf dan pengurangan resipi, setiap baris dengan tarikh, jumlah dan kosnya, siap diserahkan kepada siapa pun yang mengurus pembukuan Anda.",
  "apiErrors.invalidReference.recipeMustBelongBusiness": "Resipi harus milik perniagaan ini.",
  "apiErrors.invalidReference.purchaseOrderMustBelongBusiness": "Pesanan pembelian harus milik perniagaan ini.",
  "apiErrors.batchNeedsProduct": "Menjalankan kelompok memerlukan resipi dengan produk persediaan yang terhubung.",
  "apiErrors.invoiceFileInvalid": "Sila hantar fail PDF atau imej di bawah 25 MB.",
