  "training.lessons.owner-ebay-connect.step1": "Buka Sambungan kedai dalam talian (dalam kumpulan Jualan) dan ketik Sambungkan eBay. Anda log masuk di halaman eBay sendiri — apl tidak pernah melihat kata laluan eBay anda.",
