  "training.lessons.owner-ebay-connect.step5": "Jualan sepadan mengikut SKU, UPC, atau ISBN — mana-mana satu daripada ketiga-tiganya yang dibawa oleh penyenaraian. Jika jualan tidak dapat sepadan, ia menunggu di bawah 'Jualan yang perlu dipadankan' di halaman Sambungan kedai dalam talian: pautkannya kepada produknya sekali, dan jualan itu — dan jualan masa depan sepertinya — merekodkan diri sendiri. 'Semak jualan sekarang' mengambil apa sahaja yang terkini, dan Putuskan sambungan menghentikan sambungan; jualan yang sudah direkodkan kekal.",
